#pragma once

#include "PolySynth/Instrument.h"
#include "PolySynth/MidiSink.h"
#include "PolySynth/MidiSource.h"

#include "InstrumentTypeRegistry.h"
#include "InstrumentVoice.h"
#include "config.h"

#include "PolySynth/Sequencer.h"
#include "PolyUtil/misc.h"

#include <functional>
#include <memory>
#include <optional>

#include <boost/container/static_vector.hpp>

namespace polysynth
{
/**
 * @brief Implementation of Instrument API.
 *
 * Based on an assigned patch it generates sound when triggered with midi note events from
 * the connected MidiSource.
 * The sound is generated by InstrumentVoice instances that are created by
 * factory function provided in InstrumentType.
 * InstrumentType is obtained from InstrumentTypeRegistry, based on instrumentTypeId which
 * is provided by Patch::Metadata.
 *
 * Voice allocation algorithm is implemented in findVoiceForNote.
 * Related incoming Midi events are passed to the same InstrumentVoice instance
 * based on sourceId value.
 */
class InstrumentImpl final
  : public Instrument
  , public Patch::ParamChangeListener
  , public std::enable_shared_from_this<InstrumentImpl>
{
  public:
    struct InstrumentContext
    {
        const std::unordered_map<std::string, std::shared_ptr<MidiSink>>& midiOutputs;
        TempoProvider tempoProvider = nullptr;
    };

    ~InstrumentImpl() override;
    DELETE_COPY_MOVE(InstrumentImpl);
    static std::shared_ptr<InstrumentImpl> create(
      int instrumentId,
      std::shared_ptr<InstrumentTypeRegistry> instrumentTypeRegistry);

    [[nodiscard]] int getVoiceCount() const override;
    void setVoiceCount(int voiceCount) override;
    void reset() override;

    void assignPatch(std::shared_ptr<Patch> patch) override;
    void connect(MidiSource& midiSource) override;
    void setMidiChannel(int channel) override;
    [[nodiscard]] int getMidiChannel() const override;
    void setLocalMode(LocalMode mode) override;
    [[nodiscard]] LocalMode getLocalMode() const override { return localMode; };

    std::shared_ptr<Patch> getPatchAssigned() const { return patchAssigned; };
    void onParamChange(int paramId,
                       Patch::optional_paramvalue_t newValue,
                       Patch::ParamChangeSource source,
                       tiny_optional<int> voiceId) override;
    void onPatchReset() override;
    void renderAudioBuffer(std::optional<AudioBufferStereoRef> inputBuffer,
                           AudioBufferStereoRef outputBuffer,
                           std::span<AudioBufferRef> auxOutBuffer);

    void onMidiEvent(const MidiEvent& event, MidiSource::Type sourceType, int sourceId);

    void setup(const InstrumentContext& context);

    void setSeqConfigChanged(std::function<void()> seqConfigChanged_);

  private:
    static constexpr int kDefaultVoiceCount = 1;
    static constexpr int kNotesStackSize = 8;

    struct Voice
    {
        std::unique_ptr<InstrumentVoice> voice;
        int ticksSinceNoteOn = 0;
        boost::container::static_vector<int, kNotesStackSize> noteSourceIds = {};
    };

    boost::container::static_vector<Voice, kMaxInstrumentVoices> voices;
    int voicesInstrumentTypeId = -1;

    std::array<std::array<sample_t, kAudioBufferSize>, 2> tempBuffer = {};

    int instrumentId;
    int midiChannel = 0;
    std::shared_ptr<MidiSink> midiSink = nullptr;
    LocalMode localMode = LocalMode::kOn;

    std::shared_ptr<InstrumentTypeRegistry> instrumentTypeRegistry;

    std::vector<std::shared_ptr<MidiSource::MidiEventCallback>> midiEventsCallbacks;

    std::shared_ptr<Patch> patchAssigned = nullptr;

    TempoProvider tempoProvider;

    InstrumentImpl(int instrumentId,
                   std::shared_ptr<InstrumentTypeRegistry> instrumentTypeRegistry_);

    template<class Func>
    void executeOnSourceVoices(int sourceId, Func func);
    template<class Func>
    void executeOnNoteVoice(uint8_t note, Func func);
    template<class Func>
    void executeOnAllVoices(Func func);

    Voice& findVoiceForNote(uint8_t newNote);

    void handleMidiCC(const MidiEvent::Data::ControlChange& controlChange);
    void handleNoteOn(const MidiEvent& event, int sourceId);
    void handleNoteOff(const MidiEvent& event, int sourceId);
    void handleAftertouch(const MidiEvent::Data::Note& note, int sourceId);

    void sendParamCC(int paramId, Patch::paramvalue_t newValue);
    void updateAllPatchParams(Patch::ParamChangeSource source);

    bool recreateVoices(int voiceCount);

    float getTempo() const;
};
}
